from itertools import product

# Function to check if a number is composed only of digits 0 and 2
def is_valid_number(num):
    return all(digit in '02' for digit in str(num))

# Generate numbers using digits 0 and 2 and check for the smallest multiple of 30
for length in range(1, 20):  # Arbitrarily large upper limit to ensure we find the solution
    for digits in product('02', repeat=length):
        num = int(''.join(digits))
        if num % 30 == 0 and is_valid_number(num):
            result = num
            break
    else:
        continue
    break

print(f"\boxed{{result}}")

