from math import gcd
from functools import reduce

# Function to compute the least common multiple (LCM) of two numbers
def lcm(a, b):
    return a * b // gcd(a, b)

# Function to compute the LCM of a list of numbers
def lcm_multiple(numbers):
    return reduce(lcm, numbers)

# List of divisors excluding 7 since we need the remainder to be 0 when divided by 7
divisors = [2, 3, 4, 6]
lcm_value = lcm_multiple(divisors)

# Rosa's age minus 1 must be a multiple of the LCM of 2, 3, 4, and 6
# So Rosa's age is of the form lcm_value * k + 1 for some integer k
# We need to find the smallest such age that is also a multiple of 7 and less than 75
for k in range(1, 75 // lcm_value + 1):
    age = lcm_value * k + 1
    if age % 7 == 0 and age < 75:
        result = age
        break

print(f"\boxed{{{result}}}")

